gst_percent_expected = 0.18
gst_margin = 0.005
min_confidence = 0.80
money_tolerance = 1
po_variance = 0.02

results = []

for item in _items:
    mock = item['json']
    invoice = mock['output']
    reasons = []

    supplier = invoice.get('supplier')
    ntn = invoice.get('ntn')
    invoice_number = invoice.get('invoice_number')
    invoice_date = invoice.get('invoice_date')
    po_number = invoice.get('po_number')
    payment_terms = invoice.get('payment_terms')
    subtotal = invoice.get('subtotal')
    gst_percent = invoice.get('gst_percent')
    gst_amount = invoice.get('gst_amount')
    total = invoice.get('total')
    confidence = invoice.get('confidence')

    mock_po = mock.get('mock PO Number')
    mock_supplier = mock.get('mock Supplier')
    mock_total = mock.get('mock Expected total (PKR)')

    if po_number and mock_po:
        if po_number != mock_po:
            reasons.append('PO number mismatch')

    if supplier and mock_supplier:
        if supplier != mock_supplier:
            reasons.append('supplier mismatch')

    if total is not None and mock_total is not None:
        variance = abs(mock_total - total) / mock_total
        if variance > po_variance:
            reasons.append('PO total variance too high')

    if gst_percent is not None:
        if abs(gst_percent - gst_percent_expected) > gst_margin:
            reasons.append('GST rate not correct')

    if subtotal is not None and gst_percent is not None and gst_amount is not None:
        expected_gst = subtotal * gst_percent
        if abs(expected_gst - gst_amount) > money_tolerance:
            reasons.append('GST amount error')

    if subtotal is not None and gst_amount is not None and total is not None:
        expected_total = subtotal + gst_amount
        if abs(expected_total - total) > money_tolerance:
            reasons.append('total error')

    line_items = invoice.get('line_items')
    line_sum = 0
    if line_items is not None:
        for i in line_items:
            qty = i.get('quantity')
            price = i.get('price_per_unit')
            line_amount = i.get('line_amount')

            if qty is None:
                reasons.append('line item missing quantity')
            elif price is None:
                reasons.append('line item missing price')
            elif line_amount is None:
                reasons.append('line item missing amount')
            else:
                check = qty * price
                if abs(check - line_amount) > money_tolerance:
                    reasons.append('line math error')
                line_sum = line_sum + line_amount

        if subtotal is not None:
            if abs(line_sum - subtotal) > money_tolerance:
                reasons.append('line items do not sum to subtotal')

    if not supplier:
        reasons.append('missing field: supplier')
    if not ntn:
        reasons.append('missing field: ntn')
    if not invoice_number:
        reasons.append('missing field: invoice_number')
    if not invoice_date:
        reasons.append('missing field: invoice_date')
    if not po_number:
        reasons.append('missing field: po_number')
    if not payment_terms:
        reasons.append('missing field: payment_terms')

    if confidence:
      if confidence < min_confidence:
        reasons.append('low confidence')
    else:
      reasons.append('low confidence')

    if len(reasons) == 0:
        status = 'approve'
    else:
        status = 'review'

    reason_text = '; '.join(reasons)

    results.append({
        'json': {
            'invoice_number': invoice_number,
            'status': status,
            'reasons': reason_text
        }
    })

return results
